"""✒️ Story Quill: guided writing prompts modelled on Cambridge English writing task types.
Each prompt: genre, part (Cambridge-style task label), title, task (task card), points (content points the learner must cover;
each has `keys` = word-start prefixes / 're:' regexes, or `sets` + `need` for 'discuss TWO of three' style points),
words (target range), phrases (prompt-specific useful language, merged with the level bank), model (model answer).
Optional: email (an incoming message to reply to), texts (C2 Part 1 source texts), firstLine (B1 story).
Built by build_data.py into data/<level>/writing.json (validated: word ranges, keys found in the model, >= 6 per level)."""

COLOURS = ["red", "blue", "green", "yellow", "pink", "white", "black", "brown", "orange", "purple", "grey", "gray", "gold", "silver"]
DAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday", "weekend", "tomorrow", "tonight", "next week"]
OPINION = ["in my opinion", "in my view", "i believe", "i think", "personally", "to my mind", "i feel", "i agree", "i disagree", "i am convinced", "i would argue", "from my point of view"]
ADD_IDEA = ["re:\\b(another|a further|a third|finally|lastly|last but not least|moreover|furthermore|what is more|in addition|additionally)\\b"]
SUGGEST = ["shall we", "let's", "let us", "how about", "what about", "why don't", "we could", "would you like", "do you want", "maybe we", "could we", "can we"]
CONCLUDE = ["on balance", "ultimately", "in conclusion", "to conclude", "all things considered", "overall", "to sum up", "taking everything into account", "my own view", "i would contend", "i am inclined"]
EVALUATE = ["convincing", "persuasive", "valid", "overlook", "fail to", "underestimate", "compelling", "flawed", "oversimplif"]
T1 = ["first text", "first writer", "text 1", "the former", "first author", "first extract"]
T2 = ["second text", "second writer", "text 2", "the latter", "second author", "second extract"]

def P(label, keys=None, sets=None, need=None):
    d = {"label": label}
    if keys: d["keys"] = keys
    if sets: d["sets"] = sets; d["need"] = need or len(sets)
    return d

AGE = ["years old", "re:\\bi am (\\d+|five|six|seven|eight|nine|ten|eleven|twelve)\\b"]
WRITING = {}

